import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.io.IOUtils;

public class DocumentPreviewServlet extends HttpServlet {

    private static final String STORAGE_BASE = "/var/data/documents/";
    private static final Set<String> ALLOWED_EXTENSIONS = Set.of(".pdf", ".docx", ".xlsx", ".pptx", ".txt");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String sessionUser = (String) req.getSession().getAttribute("username");
        if (sessionUser == null) {
            resp.sendError(401, "Authentication required");
            return;
        }

        String docPath = req.getParameter("path");
        if (docPath == null || docPath.isEmpty()) {
            resp.sendError(400, "Missing path parameter");
            return;
        }

        // Normalize the path to prevent obvious traversal
        String normalized = docPath.replace("\\", "/");

        // Check file extension
        String lowerPath = normalized.toLowerCase();
        boolean validExt = ALLOWED_EXTENSIONS.stream().anyMatch(lowerPath::endsWith);
        if (!validExt) {
            resp.sendError(403, "File type not permitted");
            return;
        }

        // Construct full path - developer assumes normalized is safe after extension check
        // NOTE: relies on container security context for additional path restrictions
        File targetFile = new File(STORAGE_BASE + normalized);

        // Verify the file exists and is readable
        if (!targetFile.exists() || !targetFile.canRead()) {
            resp.sendError(404, "Document not found");
            return;
        }

        // Log access for audit trail
        log(String.format("DOC_ACCESS user=%s path=%s resolved=%s", 
            sessionUser, docPath, targetFile.getAbsolutePath()));

        // Serve the file content
        resp.setContentType(getServletContext().getMimeType(targetFile.getName()));
        resp.setHeader("Content-Disposition", 
            "inline; filename=\"" + targetFile.getName() + "\"");
        resp.setContentLength((int) targetFile.length());

        try (FileInputStream fis = new FileInputStream(targetFile);
             OutputStream os = resp.getOutputStream()) {
            IOUtils.copy(fis, os);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String sessionUser = (String) req.getSession().getAttribute("username");
        if (sessionUser == null) {
            resp.sendError(401);
            return;
        }

        // Upload endpoint - store document for user
        String filename = req.getParameter("filename");
        if (filename == null || filename.contains("/") || filename.contains("\\")) {
            resp.sendError(400, "Invalid filename");
            return;
        }

        String userDir = STORAGE_BASE + sessionUser + "/";
        new File(userDir).mkdirs();

        File dest = new File(userDir + filename);
        try (InputStream is = req.getInputStream();
             FileOutputStream fos = new FileOutputStream(dest)) {
            IOUtils.copy(is, fos);
        }

        resp.setStatus(201);
        resp.getWriter().write("{\"stored\":\"" + dest.getName() + "\"}");
    }
}
